#!/bin/sh
# Name: Embrith Starter
# Author: Embrith Contributors
# DontUseFBInk
# Icon: data:image/png;base64,
#
# 正常使用: 先安装或更新(见 modules/install/update.sh), 再启动完整的安卓(桌面, 手势), 不限时. 在安卓桌面按"退出安卓", 或长按屏幕右下角 2 秒, 回到 Kindle.
# 安装包放在 /mnt/us/embrith/src/, 程序安装在 /mnt/us/system/embrith/.
( setsid sh -c '
S=/mnt/us/embrith; D=/mnt/us/system/embrith; mkdir -p $S/logs
U=$S/src/modules/install/update.sh; [ -f $U ] || U=$D/modules/install/update.sh
{ echo "== $(date)"
  if [ -f $U ]; then sh $U && sh $D/embrith.sh start full 0; else echo "no install package and no installed copy"; fi
  echo "== done"; } >> $S/logs/last-run.txt 2>&1
' </dev/null >/dev/null 2>&1 & )
